package io.github.mbanucu.wirelessadbkeeper;

/**
 * The small part of Base64 that ADB key handling needs.
 *
 * <p>Deliberately not {@code java.util.Base64} or {@code android.util.Base64}:
 * {@link AdbKey} is also exercised by the host-side probes in {@code tools/},
 * which compile and run as plain Java, so this codec stays plain Java too.
 *
 * <p>Standard alphabet, padding required. Decoding rejects anything that is not
 * a whole number of four-character groups; that is enough validation for key
 * material and PEM bodies, which are generated by adb or by this app.
 */
final class Base64Codec {
    private static final char[] ALPHABET =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".toCharArray();
    private static final int[] VALUES = new int[128];

    static {
        java.util.Arrays.fill(VALUES, -1);
        for (int i = 0; i < ALPHABET.length; i++) {
            VALUES[ALPHABET[i]] = i;
        }
    }

    private Base64Codec() {}

    static String encode(byte[] data) {
        StringBuilder out = new StringBuilder((data.length + 2) / 3 * 4);
        for (int i = 0; i < data.length; i += 3) {
            int b0 = data[i] & 0xff;
            int b1 = i + 1 < data.length ? data[i + 1] & 0xff : 0;
            int b2 = i + 2 < data.length ? data[i + 2] & 0xff : 0;
            out.append(ALPHABET[b0 >>> 2]);
            out.append(ALPHABET[((b0 & 0x03) << 4) | (b1 >>> 4)]);
            out.append(i + 1 < data.length
                    ? ALPHABET[((b1 & 0x0f) << 2) | (b2 >>> 6)] : '=');
            out.append(i + 2 < data.length ? ALPHABET[b2 & 0x3f] : '=');
        }
        return out.toString();
    }

    static byte[] decode(String text) {
        if (text.length() % 4 != 0) {
            throw new IllegalArgumentException("bad base64 length " + text.length());
        }
        int padding = 0;
        if (text.endsWith("==")) {
            padding = 2;
        } else if (text.endsWith("=")) {
            padding = 1;
        }
        byte[] out = new byte[text.length() / 4 * 3 - padding];
        int offset = 0;
        for (int i = 0; i < text.length(); i += 4) {
            int v0 = value(text.charAt(i));
            int v1 = value(text.charAt(i + 1));
            int v2 = text.charAt(i + 2) == '=' ? 0 : value(text.charAt(i + 2));
            int v3 = text.charAt(i + 3) == '=' ? 0 : value(text.charAt(i + 3));
            if (offset < out.length) out[offset++] = (byte) ((v0 << 2) | (v1 >>> 4));
            if (offset < out.length) out[offset++] = (byte) ((v1 << 4) | (v2 >>> 2));
            if (offset < out.length) out[offset++] = (byte) ((v2 << 6) | v3);
        }
        return out;
    }

    private static int value(char c) {
        int value = c < VALUES.length ? VALUES[c] : -1;
        if (value < 0) {
            throw new IllegalArgumentException("bad base64 character '" + c + "'");
        }
        return value;
    }
}
